"""Plain-language purchase synthesis from the server snapshot."""
CSS='''
.po-purchase-summary .po-summary-action{color:inherit;text-decoration:underline;text-underline-offset:3px;cursor:pointer}.po-purchase-summary .po-summary-action:hover{color:#1950f5}.po-purchase-summary .po-summary-action:focus-visible{outline:2px solid #1950f5;outline-offset:4px;border-radius:3px}

.po-purchase-summary{margin:16px 0;padding:18px;border:1px solid #bfd2ed;border-radius:8px;background:#f1f6ff;color:#142e52}.po-purchase-summary h3{font-size:17px!important;margin:0 0 12px}.po-purchase-summary p,.po-purchase-summary li{font-size:14px;line-height:1.5}.po-purchase-summary .verdict{border-left:5px solid #6483ac;padding:8px 12px;background:#e4edfc}.po-purchase-summary[data-status="SHORTFALL"] .verdict{border-color:#b32828;background:#fff0ef}.po-purchase-summary[data-status="WITHIN_DECLARED_SCENARIO"] .verdict{border-color:#238545;background:#eaf8ee}.po-purchase-summary dl{display:flex;flex-wrap:wrap;gap:12px}.po-purchase-summary dl div{flex:1;min-width:145px}.po-purchase-summary dd{margin:6px 0;font-size:20px;font-weight:bold}.po-purchase-summary dt{font-size:13px}.po-purchase-summary summary{font-size:14px;font-weight:bold}.po-summary-stock{font-weight:650}.po-summary-stock::before{content:'●';margin-right:8px}.po-summary-stock[data-tone=green]{color:#195d32}.po-summary-stock[data-tone=amber]{color:#805300}.po-summary-stock[data-tone=red]{color:#932c25}
'''
JS=r'''
(function(){
 const live=document.createElement('section');live.id='po-purchase-summary';$('po-alternatives-table').before(live);
 function paragraph(box,text){const p=document.createElement('p');p.textContent=text;box.append(p)}
 function actionLink(parent,message,saved){
 const link=document.createElement('a');link.className='po-summary-action';link.textContent=message;
 let target,step,parameters=false;
 if(/horizonte|tesorería mínima|parámetros/i.test(message))parameters=true;
 else if(/cantidad|fecha de entrega/i.test(message)){target=$('form').elements.quantity;step='po-references'}
 else if(/stock|cobertura|consumo|recepción|supuestos|planificación/i.test(message)){target=$('po-stock-enabled');step='po-references'}
 else if(/alternativa|compara|condiciones de compra/i.test(message)){target=$('po-alternatives-table');step='po-conditions'}
 else if(/pago|cuota|calendario|vencimiento/i.test(message)){target=$('po-payments');step='po-payments'}
 else if(/precio|importe|IVA|portes|descuento/i.test(message)){target=$('po-conditions');step='po-conditions'}
 else if(/proveedor|confirma|soporte|acuerdo/i.test(message)){step='po-guide-agreement'}
 else{parent.append(document.createTextNode(message));return}
 if(saved&&!parameters){step='po-save';target=$('review-panel');link.title='Consultar el estudio guardado. Para modificar sus datos, crea un borrador desde este estudio.'}
 link.href=parameters?'#parameters-search':'#'+(target?.id||step);link.addEventListener('click',event=>{event.preventDefault();if(parameters){view('parametros');const search=$('parameters-search');if(search){search.value=/horizonte/i.test(message)?'P-FIN-001':'P-FIN-002';search.dispatchEvent(new Event('input',{bubbles:true}));search.focus();search.scrollIntoView({block:'center'})}return}window.purchaseGuideNavigate?.(step,true);if(target){if(!saved&&target.matches('input,select,textarea')){window.purchaseGuideOpenField?.(target)}else{for(let node=target.parentElement;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;target.scrollIntoView({block:'center'});target.tabIndex=-1;target.focus({preventScroll:true})}}});parent.append(link)
 }
 function render(box,r,saved){box.replaceChildren();box.className='po-purchase-summary';const h=document.createElement('h3');h.textContent=saved?'SÍNTESIS DE LA COMPRA GUARDADA':'SÍNTESIS DE LA COMPRA';box.append(h);const s=r?.purchase_summary;
 if(!s){box.dataset.status='PENDING';paragraph(box,saved?'Este estudio anterior no conserva una síntesis. Consulta sus resultados guardados; no se reconstruye con datos actuales.':r?.message||'Recalculando con las condiciones actuales…');return}
 box.dataset.status=s.status;const verdict=document.createElement('p');verdict.className='verdict';const strong=document.createElement('strong');strong.textContent={SHORTFALL:'FALTA DINERO EN LA PREVISIÓN',WITHIN_DECLARED_SCENARIO:'DINERO PREVISTO SUFICIENTE',PENDING:'FALTAN DATOS PARA CALCULAR'}[s.status];verdict.append(strong);box.append(verdict);
 const metrics=document.createElement('dl');for(const f of s.facts){const item=document.createElement('div'),label=document.createElement('dt'),value=document.createElement('dd');label.textContent=f.label;value.textContent=money(f.value)+' EUR';item.append(label,value);metrics.append(item)}box.append(metrics);
 const stockLine=document.createElement('p');stockLine.className='po-summary-stock';stockLine.dataset.tone=['NOT_ASSESSED','REFERENCE_ONLY'].includes(s.stock.status)?'amber':s.stock.current_meets_target?'green':'red';stockLine.textContent='Stock: '+(s.stock.status==='REFERENCE_ONLY'?s.stock.message:s.stock.status==='NOT_ASSESSED'?'faltan datos para calcular la cobertura.':s.stock.current_meets_target?'la cantidad cubre el objetivo indicado.':'revisa la cantidad o la fecha de entrega.');if(['NOT_ASSESSED','REFERENCE_ONLY'].includes(s.stock.status)||!s.stock.current_meets_target){const message=stockLine.textContent;stockLine.replaceChildren();actionLink(stockLine,message,saved)}box.append(stockLine);
 const next=document.createElement('p'),label=document.createElement('strong');label.textContent=saved?'SIGUIENTE ACCIÓN AL GUARDAR: ':'SIGUIENTE ACCIÓN: ';const action=s.status==='PENDING'?s.next_action:s.status==='SHORTFALL'?(s.alternatives.length?'Compara otras condiciones de compra.':'Revisa importes y fechas de pago.'):s.stock.status==='REFERENCE_ONLY'?'Revisa y confirma la planificación del libro.':s.stock.status==='NOT_ASSESSED'?'Completa los datos de stock.':!s.stock.current_meets_target?'Revisa cantidad y fecha de entrega.':'Confirma las condiciones con el proveedor.';next.append(label);actionLink(next,action,saved);box.append(next);
 const details=document.createElement('details'),title=document.createElement('summary');title.textContent='Saber más · cálculo, riesgos y fuentes';details.append(title);paragraph(details,s.title+'. '+s.explanation);paragraph(details,s.stock.message+' '+s.stock.limitation);const detailed=document.createElement('p');detailed.append(document.createTextNode('Siguiente acción detallada: '));actionLink(detailed,s.next_action,saved);details.append(detailed);if(s.sensitivity){const stress=s.sensitivity;paragraph(details,'Si no llega el cobro '+stress.flow_id+' ('+money(stress.amount)+' EUR · '+stockDate(stress.due_date)+'): '+(stress.reserve_respected?'se mantiene la reserva prevista.':'faltan '+money(stress.deficit)+' EUR para la reserva.')+' Es una hipótesis, no una previsión de impago.');}
 for(const a of s.alternatives){paragraph(details,(a.reference||'Alternativa')+' · '+a.title+' · '+stockNumber(a.quantity)+' '+a.unit+' · Total '+money(a.total)+' EUR · Diferencia de desembolso frente a la activa: '+money(-Number(a.savings))+' EUR. '+(a.same_quantity?'Mantiene la cantidad.':'Cambia la cantidad: la diferencia no es solo una mejora de precio.')+' Aceptación del proveedor sin confirmar.');paragraph(details,a.basis)}
 if(!s.alternatives.length)paragraph(details,s.status==='PENDING'?'Las alternativas requieren completar la simulación.':'No se han conservado alternativas comprobadas en este estudio.');
 const list=document.createElement('ul');for(const text of s.pending){const li=document.createElement('li');actionLink(li,text,saved);list.append(li)}details.append(list);
 for(const text of s.stock.missing||[]){const p=document.createElement('p');actionLink(p,text.message,saved);details.append(p)}
 paragraph(details,'Fuentes de los importes: cálculo comercial, escenario de tesorería y reserva activada. Stock: '+s.stock.source+'.');paragraph(details,'Versión documental: '+(s.references.documentary_context_fingerprint||'Sin referencia')+' · Fuente financiera: '+(s.references.financial_source_fingerprint||'Sin referencia')+' · Huella del estudio: '+(r.analysis_fingerprint||'Sin huella'));paragraph(details,s.scope);box.append(details);paragraph(box,'Previsión de prueba · Guardar no confirma la compra.');
 }
 window.renderPurchaseSummary=(box,r,editable)=>{if(editable)render(live,r,false);else{const section=document.createElement('section');render(section,r,true);box.append(section)}};
 window.showSavedPrimaryPurchaseSummary=r=>render(live,r,true);
 window.clearPurchaseSummary=()=>render(live,{message:'Recalculando con las condiciones actuales…'},false);
})();
'''
